/** Types for the measured layout of an imported store environment (generated by tools/assets/build_env.py). */
export type Vec3 = [number, number, number];

export interface Box {
  min: Vec3;
  max: Vec3;
}

/** One side of a gondola run: products stand on `boards` between `frontEdge` and `backEdge`, facing `normal`. */
export interface ShelfFace {
  id: string;
  run: string;
  normal: Vec3; // unit vector the product fronts face (into the aisle)
  frontEdge: number; // coordinate along the normal axis of the shelf lip
  backEdge: number; // coordinate of the center divider
  bays: [number, number][]; // usable spans along the face (between uprights)
  boards: number[]; // board top-surface heights (m)
  clearance: number; // vertical space per board
}

export interface EnvLayout {
  source: string;
  interior: Box;
  ceilingY: number;
  walls: Box[];
  fixtures: Box[];
  runs: { id: string; box: Box }[];
  faces: ShelfFace[];
  checkout: Box | null;
}
